public int kruskals(int n, int[][] edges) {
    Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
    int[] comp = new int[n + 1];
    for (int i = 1; i <= n; i++) comp[i] = i;
    int total = 0, used = 0;
    for (int[] e : edges) {
        int u = e[0], v = e[1], w = e[2];
        if (comp[u] != comp[v]) {
            int oldLabel = comp[v], newLabel = comp[u];
            for (int i = 1; i <= n; i++) {       // relabel whole component
                if (comp[i] == oldLabel) comp[i] = newLabel;
            }
            total += w;
            if (++used == n - 1) break;
        }
    }
    return total;
}

