private int[] parent, rank_;

public int kruskals(int n, int[][] edges) {
    Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
    parent = new int[n + 1];
    rank_ = new int[n + 1];
    for (int i = 1; i <= n; i++) parent[i] = i;
    int total = 0, used = 0;
    for (int[] e : edges) {
        if (union(e[0], e[1])) {        // true only if they were separate
            total += e[2];
            if (++used == n - 1) break;
        }
    }
    return total;
}

private int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];  // path compression (halving)
        x = parent[x];
    }
    return x;
}

private boolean union(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return false;          // same component → would form a cycle
    if (rank_[ra] < rank_[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;
    if (rank_[ra] == rank_[rb]) rank_[ra]++;
    return true;
}

