def kruskals(self, n: int, edges: list[list[int]]) -> int:
    edges.sort(key=lambda e: e[2])
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path compression (halving)
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False                    # same component → cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    total = used = 0
    for u, v, w in edges:
        if union(u, v):                     # only when u, v were separate
            total += w
            used += 1
            if used == n - 1:
                break
    return total

